package org.apache.commons.jxpath.ri.axes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import org.apache.commons.jxpath.BasicNodeSet;
import org.apache.commons.jxpath.ri.EvalContext;
import org.apache.commons.jxpath.ri.axes.BasicNodeSet;
import org.apache.commons.jxpath.ri.axes.EvalContext;
import org.apache.commons.jxpath.ri.axes.NodePointer;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for UnionContext.setPosition
 */
public class UnionContext_setPosition_TriageGen1Test {

    @Mock
    private EvalContext mockParentContext;

    @Mock
    private EvalContext mockContext1;

    @Mock
    private EvalContext mockContext2;

    @Mock
    private BasicNodeSet mockNodeSet;

    @Mock
    private NodePointer mockPointer1;

    @Mock
    private NodePointer mockPointer2;

    private EvalContext[] contexts;

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);
        contexts = new EvalContext[]{mockContext1, mockContext2};
    }

    /**
     * Helper class to extend UnionContext for testing purposes 
     * since we need to control getNodeSet() and the super.setPosition() behavior.
     */
    private static class TestableUnionContext extends UnionContext {
        private boolean prepared = false;
        private BasicNodeSet forcedNodeSet;
        private boolean superSetPositionResult = true;

        public TestableUnionContext(EvalContext parentContext, EvalContext[] contexts) {
            super(parentContext, contexts);
        }

        // We use reflection or override if possible. 
        // Since the target method calls getNodeSet() and super.setPosition(),
        // we simulate the internal state.

        public void setPrepared(boolean prepared) {
            this.prepared = prepared;
        }

        public void setForcedNodeSet(BasicNodeSet nodeSet) {
            this.forcedNodeSet = nodeSet;
        }

        public void setSuperSetPositionResult(boolean result) {
            this.superSetPositionResult = result;
        }

        @Override
        protected org.apache.commons.jxpath.ri.axes.BasicNodeSet getNodeSet() {
            return forcedNodeSet;
        }

        // Since we cannot easily override super.setPosition() in a real inheritance 
        // unless it's a method we can mock, we assume the test environment 
        // allows us to verify the logic flow.
        // Note: In a real scenario, we'd use PowerMock if super is non-virtual, 
        // but here we assume standard JXPath structure.
    }

    /**
     * Test case where prepared is false, and contexts have nodes.
     * This covers the main branching logic: !prepared, ctx.nextSet(), ctx.nextNode(), and !pointers.contains.
     */
    @Test
    public void testSetPosition_FirstTime_WithNodes() throws Exception {
        // Using a real subclass or a spy to handle the logic
        UnionContext context = spy(new UnionContext(mockParentContext, contexts));

        // Setup mocks for the loop logic
        when(context.getNodeSet()).thenReturn(mockNodeSet);

        // Mock Context 1: Has one set, one node
        when(mockContext1.nextSet()).thenReturn(true, false);
        when(mockContext1.nextNode()).thenReturn(true, false);
        when(mockContext1.getCurrentNodePointer()).thenReturn(mockPointer1);

        // Mock Context 2: Has one set, two nodes (one duplicate)
        when(mockContext2.nextSet()).thenReturn(true, false);
        when(mockContext2.nextNode()).thenReturn(true, true, false);
        when(mockContext2.getCurrentNodePointer()).thenReturn(mockPointer1, mockPointer2);

        // We need to mock the super.setPosition if possible, but since it's a boolean return 
        // from the actual class, we test the side effects.
        // In JXPath, UnionContext extends EvalContext.

        boolean result = context.setPosition(5);

        // Verify nodeSet.add was called for unique pointers
        verify(mockNodeSet, times(1)).add(mockPointer1);
        verify(mockNodeSet, times(1)).add(mockPointer2);

        // Verify the return value (it calls super.setPosition which returns true by default in JXPath)
        assertTrue(result);
    }

    /**
     * Test case where prepared is already true.
     * This covers the branch where the initialization block is skipped.
     */
    @Test
    public void testSetPosition_AlreadyPrepared() throws Exception {
        UnionContext context = spy(new UnionContext(mockParentContext, contexts));

        // To simulate 'prepared = true', we must run the method once or use reflection
        // Since we can't easily set private 'prepared', we run it once with empty contexts
        when(mockContext1.nextSet()).thenReturn(false);
        when(mockContext2.nextSet()).thenReturn(false);

        context.setPosition(1); // First call sets prepared = true

        // Reset mock interactions
        clearInvocations(mockNodeSet);

        // Second call
        boolean result = context.setPosition(2);

        // Verify getNodeSet was NOT called again because prepared is true
        verify(context, times(1)).getNodeSet(); 
        assertTrue(result);
    }

    /**
     * Test case where contexts are empty or nextSet() is false.
     * This covers the branch where the loops are skipped.
     */
    @Test
    public void testSetPosition_NoSets() throws Exception {
        UnionContext context = spy(new UnionContext(mockParentContext, contexts));
        when(context.getNodeSet()).thenReturn(mockNodeSet);

        when(mockContext1.nextSet()).thenReturn(false);
        when(mockContext2.nextSet()).thenReturn(false);

        boolean result = context.setPosition(0);

        verify(mockNodeSet, never()).add(any());
        assertTrue(result);
    }

    /**
     * Test case for duplicate pointers within the same context or across contexts.
     * This ensures the 'if (!pointers.contains(ptr))' logic works.
     */
    @Test
    public void testSetPosition_DuplicatePointers() throws Exception {
        UnionContext context = spy(new UnionContext(mockParentContext, contexts));
        when(context.getNodeSet()).thenReturn(mockNodeSet);

        // Context 1: Two nodes, but they are the same pointer
        when(mockContext1.nextSet()).thenReturn(true, false);
        when(mockContext1.nextNode()).thenReturn(true, true, false);
        when(mockContext1.getCurrentNodePointer()).thenReturn(mockPointer1, mockPointer1);

        // Context 2: No nodes
        when(mockContext2.nextSet()).thenReturn(false);

        context.setPosition(1);

        // Should only add the pointer once
        verify(mockNodeSet, times(1)).add(mockPointer1);
    }
}
